        if (!$normalizer instanceof ObjectNormalizer) {
            return false;
        }

        try {
            if ($normalizer->className() !== $class) {
                return false;
            }
        } catch (Throwable) {
            return false;
        }

        return $this->inlinable($class, $fingerprint, $direction);
    }

    private function inlineArray(Normalizer $normalizer, string $class, string $fingerprint, Skip $direction): bool
    {
        return $normalizer instanceof ArrayNormalizer && $this->inlineObject($normalizer->innerNormalizer(), $class, $fingerprint, $direction);
    }

    /**
     * Nested objects are only inlined when this does not change the behaviour: the code of the nested class must be
     * up to date, the class must not be lazy and every middleware must skip it in this direction. Otherwise
     * they take the regular path through the hydrator.
     */
    private function inlinable(string $class, string $fingerprint, Skip $direction): bool
    {
        // a decorator around the hydrator (e.g. tracing) has to see nested objects, they must go through the root hydrator
        if ($this->hydrator->rootHydrator() !== $this->hydrator) {
            return false;
        }

        try {
            $metadata = $this->hydrator->metadata($class);
        } catch (Throwable) {
            return false;
        }

        if ($metadata->normalizer !== null || ClassFingerprint::of($metadata) !== $fingerprint) {
            return false;
        }

        if (\PHP_VERSION_ID >= 80400 && ($metadata->lazy ?? $this->hydrator->defaultLazy())) {
            return false;
        }

        foreach ($this->middlewares as $middleware) {
            if (!$middleware instanceof SkippableMiddleware) {
                return false;
            }

            $skip = $middleware->skip($metadata);

            if ($skip !== Skip::Both && $skip !== $direction) {
                return false;
            }
        }

        return true;
    }
}